 const previousPlay=kitchenPlayMiam;kitchenPlayMiam=async function(preview=false){read();if(!preview&&nativeStatus.exact&&nativeStatus.audio)return true;const played=await previousPlay(preview);if(played&&!preview&&native)for(const t of kitchenTimers.filter(t=>t.ringing))native.acknowledge(t.id,t.end);return played};
 function bytes(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
 async function captureAudio(){try{const clip=await kitchenStoredMiam();if(clip?.blob){const base64=await bytes(clip.blob);window.goblinBackupAudio={base64,type:clip.blob.type||'audio/wav',name:clip.name||'Beast Miam Miam'};if(native&&!native.saveAudio(base64))throw Error('Copie native du son refusée.');read();goblinSnapshot('manual')}}catch(e){nativeStatus.error='La copie du son reste à vérifier : '+e.message}}
